// --- New tests for Issue #1 ---

test('resolveBrickCollision: top hit flip vy and push out', () => {
  const ball = { x: 100, y: 85, r: 7, vx: 100, vy: -200 };
  const brick = { x: 80, y: 90, w: 40, h: 20 }; // ball is slightly overlapping the top
  const prevX = 100, prevY = 80;
  resolveBrickCollision(ball, brick, prevX, prevY);
  assert.equal(ball.vy, 200, 'vy should flip');
