  const brick = { x: 80, y: 90, w: 40, h: 20 }; // ball is slightly overlapping the right (x=120)
  const prevX = 130, prevY = 100;
  resolveBrickCollision(ball, brick, prevX, prevY);
  assert.equal(ball.vx, -200, 'vx should flip');
  assert.equal(ball.x, 120 + 7, 'ball should be pushed to right of brick');
});

test('resolveBrickCollision: corner hit flip both and push out', () => {
  // Ball hitting the top-left corner
  const ball = { x: 84, y: 86, r: 7, vx: 100, vy: -100 };
  const brick = { x: 80, y: 90, w: 40, h: 20 };
  const prevX = 75, prevY = 80;
  resolveBrickCollision(ball, brick, prevX, prevY);
  assert.equal(ball.vx, -100, 'vx should flip');
  assert.equal(ball.vy, 100, 'vy should flip');
});

test('resolveBrickCollision: tunnelling detection', () => {
  // Ball moves from y=80 to y=120 in one step, jumping over the brick at y=90, h=20
  const ball = { x: 100, y: 120, r: 7, vx: 0, vy: 1000 };
  const brick = { x: 80, y: 90, w: 40, h: 20 };
  const prevX = 100, prevY = 80;
  resolveBrickCollision(ball, brick, prevX, prevY);
  assert.equal(ball.vy, -1000, 'vy should flip despite jumping over');
  assert.ok(ball.y <= 117, 'ball should be pushed back to top of brick');
});

function belowField() {
  return 500;
}

